        let (nx, ny) = (-my, mx);
        // lowest surface height this bristle reaches down to
        let th = 1.0 - reach * 1.6;

        // pass 1: contact weights
        let bw = x1 - x0;
        wts.clear();
        wts.resize(bw * (y1 - y0), 0.0);
        let mut sum_w = 0.0f32;
        let mut sum_cov = 0.0f32;
        for y in y0..y1 {
            for x in x0..x1 {
                let (px, py) = (x as f32 + 0.5, y as f32 + 0.5);
                let t = if seg2 > 1e-8 { (((px - a.0) * dx + (py - a.1) * dy) / seg2).clamp(0.0, 1.0) } else { 0.0 };
                let (qx, qy) = (a.0 + dx * t - px, a.1 + dy * t - py);
                let dist = (qx * qx + qy * qy).sqrt();
                if dist > rb + 0.5 {
                    continue;
                }
                let cov = 1.0 - smoothstep(rb * 0.5, rb + 0.5, dist);
                sum_cov += cov;
                let i = y * w + x;
                let surf = (*sf.base.add(i) + 0.35 * *sf.vol.add(i)).min(1.5);
                // soft hair bends down into the valleys of the weave; stiff hog
                // bristles ride on the peaks
                let give = 0.15 + 0.45 * (1.0 - tool.stiffness).clamp(0.0, 1.0);
                let contact = smoothstep(th - give, th + 0.2, surf);
                let mut wt = cov * contact;
                if let Some(m) = clip {
                    wt *= m.data[i];
                }
                wts[(y - y0) * bw + (x - x0)] = wt;
                sum_w += wt;
            }
        }
        if sum_w <= 1e-6 {
            return;
        }

        // deposit: a share of the load, proportional to distance traveled
        let travel = (seg / s).max(rb / s * 0.5);
        // only the part of the footprint actually in contact takes paint: a
        // bristle skimming the weave peaks keeps most of its load
        let touch = (sum_w / sum_cov.max(1e-6)).min(1.0);
        let dep_total = br.vol * (1.0 - (-travel / tool.run).exp()) * touch;
        let dep_per_w = dep_total / sum_w / px_area;
        // film splitting: a bristle in wet paint always lifts some of it, even
        // when loaded; a spent bristle drinks more
        let hunger = 0.35 + 0.65 * (1.0 - br.vol / full).clamp(0.0, 1.0).powf(1.5);
        let push_k = tool.push * (seg / (2.0 * rb)).clamp(0.0, 1.0);
        let off = rb + 1.0;

        let mut got_v = 0.0f32;
        let mut got_l = [0.0f32; LAT];
        let mut got_h: Prop = [0.0, 0.0];
        let (blat, bhide) = (br.lat, br.hide);
        for y in y0..y1 {
            for x in x0..x1 {
                let wt = wts[(y - y0) * bw + (x - x0)];
                if wt <= 0.0 {
                    continue;
                }
                let i = y * w + x;
                let vol = &mut *sf.vol.add(i);
                // one stroke lifts only part of the film
                if *sf.touched.add(i) != id {
                    *sf.touched.add(i) = id;
                    *sf.floor.add(i) = *vol * (1.0 - tool.pickup);
                }
                let v = *vol;
                if v > 1e-6 {
                    let own = if *sf.stroke.add(i) == id { 0.15 } else { 1.0 };
                    let take = (v * tool.pickup * wt * hunger * own).min((v - *sf.floor.add(i)).max(0.0));
                    if take > 0.0 {
                        *vol -= take;
                        let tv = take * px_area;
                        got_v += tv;
                        let l = &*sf.lat.add(i);
                        for k in 0..LAT {
                            got_l[k] += l[k] * tv;
                        }
                        let hp = *sf.hide.add(i);
                        got_h[0] += hp[0] * tv;
                        got_h[1] += hp[1] * tv;
                    }
                }
                if dep_per_w > 0.0 {
                    sf.add(i, dep_per_w * wt, &blat, bhide);
                    *sf.stroke.add(i) = id;
                }
                // plough: move paint outward from the bristle's path, and ahead
                if push_k > 0.0 {
                    let v = *sf.vol.add(i);
                    let m = v * push_k * wt;
                    if m > 1e-6 {
                        let (px, py) = (x as f32 + 0.5, y as f32 + 0.5);
                        let side = if (px - a.0) * nx + (py - a.1) * ny >= 0.0 { 1.0 } else { -1.0 };
                        let tx = px + (nx * side * 0.75 + mx * 0.45) * off;
                        let ty = py + (ny * side * 0.75 + my * 0.45) * off;
                        if tx >= 0.0 && ty >= 0.0 && (tx as usize) < w && (ty as usize) < h {
                            let j = ty as usize * w + tx as usize;
                            // a clipped stroke can't push paint past its mask:
                            // only the accepted share moves, the rest stays
                            let m = m * clip.map_or(1.0, |c| c.data[j]);
                            if j != i && m > 0.0 {
                                let l = *sf.lat.add(i);
                                let hd = *sf.hide.add(i);
                                *sf.vol.add(i) -= m;
                                sf.add(j, m, &l, hd);
                            }
                        }
                    }
                }
            }
        }
        br.vol = (br.vol - dep_total).max(0.0);
        if got_v > 0.0 {
            for k in 0..LAT {
                got_l[k] /= got_v;
            }
            got_h[0] /= got_v;
            got_h[1] /= got_v;
            mix_into(&mut br.vol, &mut br.lat, &mut br.hide, got_v, &got_l, got_h);
        }
        let pad = (off + 2.0) as usize;
        grow(bounds, x0.saturating_sub(pad), y0.saturating_sub(pad), (x1 + pad).min(w), (y1 + pad).min(h));
    }
}

//! Wet paint sitting on top of the dry picture.
//!
//! Every pixel holds a volume of wet paint (thickness, in "layer units": 1.0
//! is one normal coat), its pigment mixture as a Mixbox latent vector (mixing
//! is linear in latent space, weighted by volume) and its hiding power
//! (0 = pure glaze, 1 = fully opaque body color). Brushes exchange paint with
//! this layer. `Canvas::dry` bakes it into the dry picture with Kubelka–Munk.

use crate::canvas::Canvas;
use crate::color::Rgb;
use crate::pigment::Pigment;
use crate::surface::COAT_UM;
use rayon::prelude::*;

pub const LAT: usize = mixbox::LATENT_SIZE;
pub type Latent = [f32; LAT];
/// Paint properties mixed by volume alongside the pigment: [hiding, stiffness].
/// Stiffness 0 = fluid, medium-rich glaze; 1 = stiff tube paint.
pub type Prop = [f32; 2];

#[inline]
fn lerp_prop(p: &mut Prop, q: Prop, a: f32) {
    p[0] += (q[0] - p[0]) * a;
    p[1] += (q[1] - p[1]) * a;
}

/// A paint as squeezed from the tube and thinned with medium.
#[derive(Clone, Copy, Debug)]
pub struct Paint {
    pub color: Rgb,
    /// Hiding power at unit thickness: 0.05 = glaze, 0.5 = scumble, 0.92 = body.
    pub hiding: f32,
    /// Stiffness: 0 = fluid, rich in medium (a glaze), 1 = stiff tube paint.
    /// Sets how the paint levels as it dries (see `surface::settle`). How
    /// much paint goes on the brush is the separate `amount` of `Held::load`.
    pub stiff: f32,
}

impl Paint {
    pub fn new(color: Rgb, hiding: f32, stiff: f32) -> Self {
        Paint { color, hiding, stiff }
    }
    pub fn body(color: Rgb) -> Self {
        Paint { color, hiding: 0.92, stiff: 1.0 }
    }
    pub fn scumble(color: Rgb) -> Self {
        Paint { color, hiding: 0.5, stiff: 0.6 }
    }
    pub fn glaze(color: Rgb) -> Self {
        Paint { color, hiding: 0.07, stiff: 0.3 }
    }
    pub fn latent(&self) -> Latent {
        mixbox::linear_float_rgb_to_latent(&self.color)
    }
}

pub(crate) struct Wet {
    pub(crate) vol: Vec<f32>,
    pub(crate) lat: Vec<Latent>,
    /// [hiding, stiffness] of the wet paint.
    pub(crate) hide: Vec<Prop>,
    /// Which stroke last laid paint here (a stroke barely re-picks its own paint).
    pub(crate) stroke: Vec<u32>,
    /// Stroke that last touched a pixel, and the film floor that stroke may
    /// not lift below (one pass lifts only part of the film).
    pub(crate) touched: Vec<u32>,
    pub(crate) floor: Vec<f32>,
    /// Id of the stroke being painted.
    pub(crate) current: u32,
    /// Dirty bounding box in pixels (x0, y0, x1, y1), if any paint is wet.
    pub(crate) dirty: Option<(usize, usize, usize, usize)>,
}

impl Wet {
    pub fn new(n: usize) -> Self {
        Wet { vol: vec![0.0; n], lat: vec![[0.0; LAT]; n], hide: vec![[0.0, 0.5]; n], stroke: vec![0; n], touched: vec![0; n], floor: vec![0.0; n], current: 0, dirty: None }
    }

    pub fn touch(&mut self, x0: usize, y0: usize, x1: usize, y1: usize) {
        self.dirty = Some(match self.dirty {
            None => (x0, y0, x1, y1),
            Some((a, b, c, d)) => (a.min(x0), b.min(y0), c.max(x1), d.max(y1)),
        });
    }

}

/// Mix `v` of (`lat`, `hide`) into a reservoir (`rv`, `rl`, `rh`).
#[inline]
pub fn mix_into(rv: &mut f32, rl: &mut Latent, rh: &mut Prop, v: f32, lat: &Latent, hide: Prop) {
    if v <= 0.0 {
        return;
    }
    let t = *rv + v;
    let a = v / t;
    for k in 0..LAT {
        rl[k] += (lat[k] - rl[k]) * a;
    }
    lerp_prop(rh, hide, a);
    *rv = t;
}


impl Canvas {
    /// Let the wet paint dry: the film levels over the surface (thin fluid
    /// paint pools in the hollows, stiff paint keeps its marks), then it is
    /// composited over the dry picture with Kubelka–Munk using the settled
    /// thickness, and the wet layer is cleared.
    pub fn dry(&mut self) {
        let Some((x0, y0, x1, y1)) = self.wet.dirty.take() else { return };
        let (w, h) = (self.f.w, self.f.h);
        let (x1, y1) = (x1.min(w), y1.min(h));
        let pad = ((2.0 / self.px_mm()).ceil() as usize).max(2);
        let ex = (x0.saturating_sub(pad), y0.saturating_sub(pad), (x1 + pad).min(w), (y1 + pad).min(h));
        let (ew, eh) = (ex.2 - ex.0, ex.3 - ex.1);
        let mut add = vec![0.0f32; ew * eh];
        let mut stiff = vec![0.5f32; ew * eh];
        for y in 0..eh {
            for x in 0..ew {
                let i = (ex.1 + y) * w + ex.0 + x;
                let v = self.wet.vol[i];
                if v >= 1e-5 {
                    add[y * ew + x] = v * COAT_UM;
                    stiff[y * ew + x] = self.wet.hide[i][1];
                }
            }
        }
        let t = self.settle(ex, &add, &stiff);
        let wet = &mut self.wet;
        let (lat, hide) = (&wet.lat, &wet.hide);
        self.px[ex.1 * w..ex.3 * w]
            .par_chunks_mut(w)
            .zip(wet.vol[ex.1 * w..ex.3 * w].par_chunks_mut(w))
            .zip(self.film[ex.1 * w..ex.3 * w].par_chunks_mut(w))
            .enumerate()
            .for_each(|(j, ((px, vv), ff))| {
                let y = ex.1 + j;
                for x in ex.0..ex.2 {
                    if vv[x] < 1e-5 {
                        vv[x] = 0.0;
                        continue;
                    }
                    let ti = t[j * ew + x - ex.0] / COAT_UM;
                    let i = y * w + x;
                    let c = mixbox::latent_to_linear_float_rgb(&lat[i]);
                    let pig = Pigment::with_hiding(c, hide[i][0].clamp(0.01, 0.99));
                    px[x] = pig.over(px[x], ti);
                    ff[x] += ti;
                    vv[x] = 0.0;
                }
            });
    }

    /// Total wet paint on the canvas (for tests / debugging).
    pub fn wet_total(&self) -> f64 {
        self.wet.vol.iter().map(|&v| v as f64).sum::<f64>() / (self.f.scale as f64 * self.f.scale as f64)
    }
}

            }
        }
    }

    /// Silhouette mask of the limbs (for glazing, mist, clipping).
    pub fn mask(&self, c: &Canvas, limbs: &[Limb]) -> Mask {
        let mut shape = Shape::new();
        for l in limbs {
            shape = shape.ribbon(&l.pts, &l.w);
        }
        Mask::from_shape(c.f, shape)
    }

    /// Paint the tree with simulated brushes: every limb a single drag of a
    /// round sable as wide as the limb (the bristles give bark streaks), twigs
    /// with a rigger, then a light dry-brush pass along the lit edge.
    pub fn paint(&self, c: &mut Canvas, dark: Rgb, light: Option<Rgb>, seed: u64) -> Mask {
        let limbs = self.grow();
        let mut rng = Rng::new(seed);
        // thick to thin, like a painter blocking the tree in
        let mut order: Vec<&Limb> = limbs.iter().collect();
        order.sort_by(|a, b| b.w[0].partial_cmp(&a.w[0]).unwrap());
        let paint = Paint { color: dark, hiding: 0.95, stiff: 0.9 };
        for l in &order {
            let w0 = l.w[0];
            let w1 = *l.w.last().unwrap();
            let tool = if w0 < 0.9 {
                Tool { width: w0 * 1.6, length: w0 * 3.0, splay: 0.15, stiffness: 0.3, ragged: 0.05, ..Tool::rigger(w0) }
            } else {
                Tool { width: w0, length: w0 * 0.5, ragged: 0.35, ..Tool::round_sable(w0) }
            };
            let mut held = Held::new(tool, rng.next_u64());
            held.load(paint, 0.9);
            // pressure sets the width: full at the base, lighter to the tip
            let p1 = (w1 / w0).clamp(0.15, 1.0);
            let g = Gesture::new(l.pts.clone()).pressure(1.0, p1).ramps(0.0, if l.depth > 2 { 0.4 } else { 0.1 }).orient(Orient::Across);
            c.drag(&mut held, &g, None);
            // a stub from a broken limb ends blunt: dab the end
        }
        if let Some(lc) = light {
            // let the dark dry, then drag a lean light scumble along the lit
            // edge with hardly any pressure: it catches only the ridges of the
            // bark strokes and the canvas tooth, broken like real dry-brush
            c.dry();
            let mask = self.mask(c, &limbs);
            // model each big limb as a lit cylinder: a few thin lean streaks
            // laid along the limb on the side facing the light (upper left),
            // stepping from half-tone near the axis to the lightest near the
            // edge; low pressure so the canvas tooth and the bark ridges break
            // them up, and each covers a random stretch of the limb
            let light_dir = (-0.75f32, -0.66f32);
            for l in limbs.iter().filter(|l| l.w[0] > 2.0) {
                let n = l.pts.len();
                let normals: Vec<(f32, f32)> = (0..n)
                    .map(|i| {
                        let a = l.pts[i.saturating_sub(1)];
                        let b = l.pts[(i + 1).min(n - 1)];
                        let (dx, dy) = (b.0 - a.0, b.1 - a.1);
                        let d = (dx * dx + dy * dy).sqrt().max(1e-4);
                        let nn = (-dy / d, dx / d);
                        if nn.0 * light_dir.0 + nn.1 * light_dir.1 >= 0.0 { nn } else { (-nn.0, -nn.1) }
                    })
                    .collect();
                // how squarely the limb faces the light: vertical limbs get a
                // clear lit side, limbs pointing at the light hardly any
                let facing = normals.iter().map(|nn| (nn.0 * light_dir.0 + nn.1 * light_dir.1).max(0.0)).sum::<f32>() / n as f32;
                let streaks = 2 + (l.w[0] / 3.0).min(3.0) as usize;
                for k in 0..streaks {
                    let u = 0.12 + 0.3 * (k as f32 + rng.range(0.0, 0.8)) / streaks as f32;
                    let tone = (0.25 + 0.75 * (k + 1) as f32 / streaks as f32) * (0.4 + 0.6 * facing);
                    let pts: Vec<(f32, f32)> = (0..n)
                        .map(|i| {
                            let w = l.w[i];
                            (l.pts[i].0 + normals[i].0 * w * u, l.pts[i].1 + normals[i].1 * w * u)
                        })
                        .collect();
                    // a random stretch of the limb
                    let a = rng.range(0.0, 0.4);
                    let b = (a + rng.range(0.35, 0.9)).min(1.0);
                    let sub = sub_path(&pts, a, b);
                    let col = crate::color::mix(dark, lc, tone, crate::color::Mix::Pigment);
                    let tool = Tool { ragged: 0.6, ..Tool::round_sable(l.w[0] * rng.range(0.1, 0.18)) };
                    let mut held = Held::new(tool, rng.next_u64());
                    held.load(Paint { color: col, hiding: 0.6, stiff: 0.4 }, rng.range(0.4, 0.8) * 0.4);
                    let g = Gesture::new(sub).pressure(rng.range(0.3, 0.5), rng.range(0.15, 0.3)).ramps(0.2, 0.4).orient(Orient::Across);
                    c.drag(&mut held, &g, Some(&mask));
                }
            }
            return mask;
        }
        self.mask(c, &limbs)
    }
}

fn dist(a: (f32, f32), b: (f32, f32)) -> f32 {
    ((a.0 - b.0).powi(2) + (a.1 - b.1).powi(2)).sqrt()
}

fn lerp(a: (f32, f32), b: (f32, f32), t: f32) -> (f32, f32) {
    (a.0 + (b.0 - a.0) * t, a.1 + (b.1 - a.1) * t)
}

/// Segment index and fraction at arc-length fraction `u` along a polyline.
fn pick_along(pts: &[(f32, f32)], u: f32) -> (usize, f32) {
    let total: f32 = pts.windows(2).map(|p| dist(p[0], p[1])).sum();
    let mut target = u * total;
    for i in 0..pts.len() - 1 {
        let d = dist(pts[i], pts[i + 1]);
        if target <= d || i == pts.len() - 2 {
            return (i, (target / d.max(1e-6)).clamp(0.0, 1.0));
        }
        target -= d;
    }
    (0, 0.0)
}

fn angle_diff(target: f32, a: f32) -> f32 {
    let mut d = target - a;
    while d > PI {
        d -= 2.0 * PI;
    }
    while d < -PI {
        d += 2.0 * PI;
    }
    d
}

fn side_of(a: f32) -> f32 {
    if a.cos() >= 0.0 { 1.0 } else { -1.0 }
}

/// The part of a polyline between arc-length fractions `a` and `b`.
fn sub_path(pts: &[(f32, f32)], a: f32, b: f32) -> Vec<(f32, f32)> {
    let (i0, t0) = pick_along(pts, a);
    let (i1, t1) = pick_along(pts, b);
    let mut out = vec![lerp(pts[i0], pts[i0 + 1], t0)];
    for p in &pts[i0 + 1..=i1] {
        out.push(*p);
    }
    out.push(lerp(pts[i1], pts[i1 + 1], t1));
    out
}
# Physics of 19th-century oil paint on canvas: sourced numbers for a simulator

**Confidence tags.** **[V]**: I read the number in the source text myself (fetched page or PDF). **[S]**: the number came from a search-engine summary of the source, and I did not read the full text. Check [S] numbers before relying on them. **[E]**: my own estimate or derivation, with the assumptions stated. Source numbers in brackets point to the list at the end.

---

## 1. Rheology and leveling

**Constitutive behavior.** Tube oil paint is a viscoplastic, shear-thinning and thixotropic suspension. A Herschel–Bulkley law fits it well: τ = τ_y + K·γ̇ⁿ, with n ≈ 0.2–0.7 [2][S].

| Quantity | Value | Tag |
|---|---|---|
| Yield stress, model ultramarine oil paint (32 vol% solids) | **10–20 Pa**. Brushstrokes came out regular and low-relief (Rz < 100 µm) | [1][V] |
| Yield stress, same paint + 4 vol% egg yolk (capillary network) | **≈3000–3200 Pa**. Strong impasto, and wrinkling suppressed | [1][V] |
| Typical tube paints | ~10–1000 Pa; stiff impasto grades above 1000 Pa | [2][S] |
| Apparent viscosity | 10⁴–10⁷ Pa·s at 0.01–0.1 s⁻¹; 10–10³ Pa·s at 10–100 s⁻¹ (brushing) | [2][S] |
| Linseed oil (the medium) | η ≈ 0.048 Pa·s, σ ≈ 33–36 mN/m at 20 °C | [6][S] |
| Stand oil | η ≈ 0.5–25 Pa·s depending on grade | [6][S] |

Impasto requires "sufficiently high yield stress preventing levelling after brush passage," while brushability depends on the *high-shear* viscosity, so stiff paint can still brush easily [1][V].

**Orchard leveling (Newtonian, thin film h ≪ λ).** A sinusoidal ridge of wavelength λ on a film of mean thickness h decays as a(t) = a₀·e^(−t/τ), with

  **τ = 3η(λ/2π)⁴ / (σh³)**  [3][V].

The dependence is λ⁴ and h⁻³, so λ and h matter far more than η or σ.

**Yield-stress floor.** Surface tension produces a leveling stress of about 8π³σha/λ³. Flow stops once τ_y exceeds it, so ridges smaller than

  **a_c = τ_y λ³ / (8π³ σ h)**

never level [4][S]. For thixotropic paint, τ_y(t) recovers after brushing, so leveling starts and then freezes with a residual mark [4][S]. With solvent evaporation, moderate yield stress can actually reduce residual unevenness [5][S].

**Worked numbers [E]** (σ = 0.035 N/m):

| Case | η | λ | h | τ (1/e time) |
|---|---|---|---|---|
| Medium-rich glaze, bristle striation | 1 Pa·s | 0.3 mm | 20 µm | 0.06 s |
| Glaze, stroke-scale ridge | 1 Pa·s | 2 mm | 20 µm | 110 s |
| Tube paint, stroke ridge, low-shear η | 10³–10⁴ Pa·s | 2 mm | 100 µm | 15 min – 2.5 h |

| τ_y | Frozen amplitude a_c, λ = 0.3 mm, h = 100 µm | a_c, λ = 2 mm, h = 300 µm |
|---|---|---|
| 15 Pa | ~0.5–1 µm (striations vanish) | ~45 µm |
| 100 Pa | ~3–6 µm | ~300 µm |
| 500 Pa | ~15–30 µm | effectively frozen |
| 3000 Pa | ~90–200 µm | frozen |

The ranges come from comparing the thin-film form with a deep-layer form, a_c ≈ τ_yλ²/(4π²σ), which I derived for h ≳ λ/2π, where the lubrication assumption fails [E]. **Conclusion:** bristle striations survive only in paint with τ_y ≳ 100 Pa. Fluid glaze paint levels its bristle marks within seconds but can keep mm-scale ridges if it has any yield stress.

## 2. Brush marks

| Fiber | Diameter | Tip | Tag |
|---|---|---|---|
| Hog bristle | 0.20–0.30 mm (fine hog 0.15–0.25) | Naturally split ("flagged") | [8][S] |
| Kolinsky/red sable | ~60–120 µm | Single fine taper | [8][S] |

In profilometry of oil paintings, the height features that best identify the painter sit at **0.2–0.4 mm**, matching the bristle widths used (**0.25 and 0.65 mm**) [7][V]. For macro impasto, *The Night Watch* has measured relief up to about 0.85 mm [42][S].

**Dry brush and scumble.** Describing Renoir's *Near the Lake*, the Art Institute of Chicago writes that he "dragged an almost dry brush across the surface, catching only the thread tops." This works even over a heavy, smooth ground: the deposit follows *contact*, not flow.
