//! Color helpers. All `Rgb` values are linear-light.

pub type Rgb = [f32; 3];

#[inline]
pub fn srgb_to_linear(c: f32) -> f32 {
    if c <= 0.04045 { c / 12.92 } else { ((c + 0.055) / 1.055).powf(2.4) }
}

#[inline]
pub fn linear_to_srgb(c: f32) -> f32 {
    let c = c.clamp(0.0, 1.0);
    if c <= 0.0031308 { c * 12.92 } else { 1.055 * c.powf(1.0 / 2.4) - 0.055 }
}

/// Parse "#rrggbb" (sRGB) into linear RGB.
pub fn hex(s: &str) -> Rgb {
    let s = s.trim_start_matches('#');
    let v = u32::from_str_radix(s, 16).expect("bad hex color");
    let f = |shift: u32| srgb_to_linear(((v >> shift) & 0xff) as f32 / 255.0);
    [f(16), f(8), f(0)]
}

/// How two colors combine.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Mix {
    /// Physical pigment mixing via Mixbox (blue + yellow = green).
    Pigment,
    /// Perceptual blend in OKLab (good for light, haze, sky glow).
    Light,
    /// Plain linear-light interpolation.
    Linear,
}

pub fn mix(a: Rgb, b: Rgb, t: f32, mode: Mix) -> Rgb {
    let t = t.clamp(0.0, 1.0);
    if t <= 0.0 {
        return a;
    }
    if t >= 1.0 {
        return b;
    }
    match mode {
        Mix::Pigment => mixbox::lerp_linear_float(&a, &b, t),
        Mix::Linear => lerp3(a, b, t),
        Mix::Light => from_oklab(lerp3(to_oklab(a), to_oklab(b), t)),
    }
}

#[inline]
pub fn lerp3(a: Rgb, b: Rgb, t: f32) -> Rgb {
    [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]
}

#[inline]
pub fn scale(a: Rgb, k: f32) -> Rgb {
    [a[0] * k, a[1] * k, a[2] * k]
}

#[inline]
pub fn luminance(c: Rgb) -> f32 {
    0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]
}

/// Multi-stop gradient; `stops` are (position, color) sorted by position.
pub fn gradient(stops: &[(f32, Rgb)], t: f32, mode: Mix) -> Rgb {
    assert!(!stops.is_empty());
    if t <= stops[0].0 {
        return stops[0].1;
    }
    for w in stops.windows(2) {
        let (p0, c0) = w[0];
        let (p1, c1) = w[1];
        if t <= p1 {
            let u = if p1 > p0 { (t - p0) / (p1 - p0) } else { 1.0 };
            // smooth the transition so stops don't show as creases
            let u = u * u * (3.0 - 2.0 * u);
            return mix(c0, c1, u, mode);
        }
    }
//! Kubelka–Munk pigments, following Curtis et al. 1997, "Computer-Generated
//! Watercolor", section 5.1:
//! https://grail.cs.washington.edu/wp-content/uploads/2015/08/curtis-1997-cgw.pdf
//!
//! A pigment is specified by how a unit-thickness layer looks over white and
//! over black. From that we derive absorption K and scattering S per channel,
//! then composite layers of any thickness over whatever is already painted.

use crate::color::Rgb;

#[derive(Clone, Copy, Debug)]
pub struct Pigment {
    pub k: Rgb,
    pub s: Rgb,
}

impl Pigment {
    /// Derive K and S from a layer's appearance over white and over black.
    pub fn from_appearance(on_white: Rgb, on_black: Rgb) -> Self {
        let mut k = [0.0; 3];
        let mut s = [0.0; 3];
        for i in 0..3 {
            let rw = on_white[i].clamp(0.004, 0.996);
            let rb = on_black[i].clamp(0.001, rw - 0.002);
            let a = 0.5 * (rw + (rb - rw + 1.0) / rb);
            let b = (a * a - 1.0).max(1e-8).sqrt();
            let z = (b * b - (a - rw) * (a - 1.0)) / (b * (1.0 - rw));
            let arcoth = 0.5 * ((z + 1.0) / (z - 1.0).max(1e-8)).ln();
            s[i] = (arcoth / b).max(0.0);
            k[i] = s[i] * (a - 1.0);
        }
        Pigment { k, s }
    }

    /// A transparent glazing pigment (hides very little).
    pub fn transparent(color: Rgb) -> Self {
        Self::with_hiding(color, 0.06)
    }

    /// Aged varnish: a clear film that only absorbs (yellows), with almost
    /// no scattering, so it warms the darks without veiling them.
    pub fn varnish(color: Rgb) -> Self {
        Self::with_hiding(color, 0.004)
    }

    /// Semi-opaque (scumbles, thin body color).
    pub fn semi(color: Rgb) -> Self {
        Self::with_hiding(color, 0.45)
    }

    /// Nearly opaque body color.
    pub fn opaque(color: Rgb) -> Self {
        Self::with_hiding(color, 0.92)
    }

    /// `hiding` = fraction of the over-white appearance that survives over black.
    pub fn with_hiding(color: Rgb, hiding: f32) -> Self {
        let on_black = [color[0] * hiding, color[1] * hiding, color[2] * hiding];
        Self::from_appearance(color, on_black)
    }
[package]
name = "paintings"
version = "0.1.0"
edition = "2024"
publish = false

[dependencies]
paint = { path = "../crates/paint" }

arguments.content:
//! Morning on the Ridge (in the manner of Caspar David Friedrich).
//!
//! An original composition: a wide dawn view over the Riesengebirge from a
//! granite tor. Long ridges recede in veils of morning mist, each paler and
//! bluer than the one before; the sun has not yet cleared the farthest ridge
//! and only its glow stands in the saddle. On the right the tor rises dark
//! against the light, and on its top stand a plain wooden cross and spruces
//! (the evergreen and the cross: faith that outlasts). On the ledge at the
//! left a single wanderer, seen from behind, faces the dawn. There is no
//! middle ground: the near rock drops straight into the misted distance.
//!
//! Order of work as Friedrich's: bought ground, underdrawing, a very thin
//! underpainting, sky, distance to foreground, figures last, finish.

use paint::color::{Mix, gradient, mix};
use paint::{Apply, Canvas, Fbm, Gesture, Ground, Held, Mask, Orient, Palette, Rgb, Shape, Style, Tool, hex, smoothstep};
use paintings::run::{Finish, Run};

const ASPECT: f32 = 1.6;
/// Where the sun is about to rise (just below the far saddle).
const SUN: (f32, f32) = (420.0, 346.0);

// ---------------------------------------------------------------- geometry

struct Ridge {
    base: f32,
    amp: f32,
    n: Fbm,
    fine: Fbm,
    /// (x, height, half width) of rounded summits / cones.
    peaks: Vec<(f32, f32, f32)>,
    col: Rgb,
    mist: Rgb,
    /// Distance below the crest over which the ridge dissolves into mist.
    fade: f32,
    /// How far below the crest the ridge is painted at all.
    depth: f32,
}

impl Ridge {
    fn crest(&self, x: f32) -> f32 {
        let mut y = self.base - self.amp * self.n.get(x, 13.7) - self.amp * 0.18 * self.fine.get(x, 3.1);
        for &(px, ph, pw) in &self.peaks {
            let d = ((x - px).powi(2) + (0.18 * pw).powi(2)).sqrt() / pw;
            y -= ph * (1.0 - d).max(0.0).powf(1.25);
        }
        y
    }
    fn slope(&self, x: f32) -> f32 {
        (self.crest(x + 3.0) - self.crest(x - 3.0)) / 6.0
    }
    fn color(&self, x: f32, y: f32) -> Rgb {
        let d = y - self.crest(x);
        let t = smoothstep(0.0, self.fade, d);
        // the glow of the sun behind the far ridges warms the haze near it
        let g = (-((x - SUN.0) / 260.0).powi(2)).exp();
        let mist = mix(self.mist, hex("#efdcb4"), g * 0.45, Mix::Light);
        mix(self.col, mist, t.powf(0.8), Mix::Light)
    }
}

fn curve(f: impl Fn(f32) -> f32) -> Vec<(f32, f32)> {
    (0..=216).map(|i| {
        let x = -40.0 + i as f32 * 5.0;
        (x, f(x))
    }).collect()
}

/// A granite block of a tor: a rounded, slightly irregular box.
struct Block {
    cx: f32,
    cy: f32,
    rx: f32,
    ry: f32,
    pts: Vec<(f32, f32)>,
}

impl Block {
    fn new(cx: f32, cy: f32, rx: f32, ry: f32, seed: u32) -> Self {
        let n = Fbm::new(seed, 3, 1.3);
        let pts = (0..36)
            .map(|i| {
                let a = i as f32 / 36.0 * std::f32::consts::TAU;
                let (ca, sa) = (a.cos(), a.sin());
                // superellipse, flatter on top (weathered woolsack blocks)
                let p = if sa < 0.0 { 3.2 } else { 2.6 };
                let r = 1.0 / (ca.abs().powf(p) + sa.abs().powf(p)).powf(1.0 / p);
                let k = 1.0 + 0.07 * n.get(ca * 2.0, sa * 2.0);
                (cx + rx * r * ca * k, cy + ry * r * sa * k)
            })
            .collect();
        Block { cx, cy, rx, ry, pts }
    }
    fn mask(&self, c: &Canvas) -> Mask {
        Mask::from_shape(c.frame(), Shape::new().smooth_poly(&self.pts))
    }
    /// Normalized position inside the block.
    fn uv(&self, x: f32, y: f32) -> (f32, f32) {
        ((x - self.cx) / self.rx, (y - self.cy) / self.ry)
    }
}

// ------------------------------------------------------------------ colors

fn sky(x: f32, y: f32) -> Rgb {
    let t = (y / 345.0).clamp(0.0, 1.0);
    let base = gradient(
        &[
            (0.0, hex("#6d84a6")),
            (0.3, hex("#94a3bb")),
            (0.55, hex("#bdb9c6")),
            (0.75, hex("#dcc6bf")),
            (0.9, hex("#ecd6b8")),
            (1.0, hex("#f1e2c2")),
        ],
        t,
        Mix::Light,
    );
    let dx = (x - SUN.0) / 380.0;
    let dy = (y - SUN.1) / 170.0;
    let g = (-(dx * dx + dy * dy)).exp();
    mix(base, hex("#f5e6bf"), g * 0.65, Mix::Light)
}

fn main() {
    let o = Run::new("fresh_mountains");
    let mut st = Style::friedrich();
    // a Dresden ground whose top layer is a patchy, lead-white-rich buff
    // (KÖR p.284) rather than the reddish ocher of the moon pictures: this is
    // a dawn picture and wants the light of the ground under the sky
    st.ground[2] = Ground { color: hex("#d2bf9f"), hiding: 0.8, um: 55.0, stiff: 0.4, apply: Apply::Brush };
    let pal: Palette = st.palette.clone();
    let mut c = st.prepare(o.width, ASPECT, o.seed);
    let f = c.frame();
    let hgt = c.height();
    if o.stage(&mut c, "ground") {
        return;
    }

    // ------------------------------------------------------------ the plan
    let ridge = |base: f32, amp: f32, seed: u32, period: f32, peaks: Vec<(f32, f32, f32)>, col: &str, mist: &str, fade: f32, depth: f32| Ridge {
        base,
        amp,
        n: Fbm::new(seed, 3, period),
        fine: Fbm::new(seed + 50, 3, period * 0.15),
        peaks,
        col: hex(col),
        mist: hex(mist),
        fade,
        depth,
    };
    let ridges = vec![
        // the farthest chain with its cone (a Schneekoppe of my own)
        ridge(338.0, 10.0, 3, 380.0, vec![(215.0, 36.0, 120.0), (640.0, 10.0, 160.0)], "#b3a8b4", "#dccfc6", 26.0, 60.0),
        ridge(352.0, 13.0, 5, 300.0, vec![(90.0, 14.0, 110.0), (560.0, 12.0, 90.0)], "#9d93a6", "#d6cac3", 24.0, 60.0),
        ridge(372.0, 15.0, 7, 260.0, vec![(330.0, 16.0, 120.0)], "#877f96", "#d0c4bd", 22.0, 60.0),
        ridge(396.0, 16.0, 9, 230.0, vec![(140.0, 12.0, 90.0), (520.0, 18.0, 110.0)], "#6f6a82", "#c8bdb6", 22.0, 70.0),
        ridge(425.0, 16.0, 11, 200.0, vec![(460.0, 14.0, 100.0)], "#56556a", "#bfb4ad", 24.0, 80.0),
        ridge(458.0, 14.0, 13, 180.0, vec![(620.0, 20.0, 150.0)], "#3f4153", "#b5aaa2", 28.0, 90.0),
    ];

    // the foreground ledge the wanderer stands on, rising into the tor
    let ledge_pts: Vec<(f32, f32)> = vec![
        (-20.0, 518.0),
        (60.0, 514.0),
        (140.0, 506.0),
        (220.0, 500.0),
        (300.0, 497.0),
        (360.0, 499.0),
        (430.0, 505.0),
        (500.0, 500.0),
        (560.0, 488.0),
        (620.0, 470.0),
        (1020.0, 450.0),
    ];
    let ledge = Mask::from_shape(f, Shape::new().below(&ledge_pts, hgt + 20.0));
    // the tor: blocks from the bottom up
    let blocks = vec![
        Block::new(600.0, 505.0, 120.0, 38.0, 1),
        Block::new(735.0, 470.0, 140.0, 55.0, 2),
        Block::new(905.0, 455.0, 135.0, 70.0, 3),
        Block::new(995.0, 395.0, 70.0, 70.0, 4),
        Block::new(770.0, 398.0, 105.0, 38.0, 5),
        Block::new(885.0, 380.0, 85.0, 42.0, 6),
        Block::new(800.0, 334.0, 80.0, 30.0, 7),
        Block::new(880.0, 320.0, 50.0, 28.0, 8),
        Block::new(808.0, 287.0, 58.0, 24.0, 9),
    ];
    let bmasks: Vec<Mask> = blocks.iter().map(|b| b.mask(&c)).collect();
    let mut fg = ledge.clone();
    for m in &bmasks {
        fg = fg.union(m);
    }
    let cross_at = (806.0, 266.0);
    let figure_at = (262.0, 498.0);

    // ------------------------------------------------------ underdrawing
    // graphite-like thin gray lines: the ridge crests, the blocks, the cross
    {
        let lead = pal.paint(hex("#5d5a58"), 0.55);
        let mut pencil = Held::new(Tool { width: 0.7, ..Tool::rigger(0.7) }, 5);
        for (k, r) in ridges.iter().enumerate() {
            let pts = curve(|x| r.crest(x));
            for seg in pts.chunks(30) {
                pencil.reload(lead, 0.25);
                c.drag(&mut pencil, &Gesture::new(seg.to_vec()).pressure(0.35, 0.3).shake(1.2), None);
            }
            let _ = k;
        }
        for b in &blocks {
            pencil.reload(lead, 0.3);
            let mut p = b.pts.clone();
            p.push(p[0]);
            c.drag(&mut pencil, &Gesture::new(p).pressure(0.4, 0.35), None);
        }
        pencil.reload(lead, 0.3);
        c.drag(&mut pencil, &Gesture::line(cross_at, (cross_at.0, cross_at.1 - 150.0)).pressure(0.4, 0.4).shake(0.3), None);
        c.drag(&mut pencil, &Gesture::line((cross_at.0 - 32.0, cross_at.1 - 118.0), (cross_at.0 + 32.0, cross_at.1 - 118.0)).pressure(0.4, 0.4).shake(0.3), None);
        c.dry();
    }
    if o.stage(&mut c, "drawing") {
        return;
    }

    // ------------------------------------------------ thin underpainting
    // a warm umber wash over the foreground mass only
    {
        let h = st.body().color(|_, y| mix(hex("#4a3a2c"), hex("#3a2f28"), smoothstep(450.0, 600.0, y), Mix::Pigment)).medium(0.6).clip(true).threshold(0.05).length(20.0, 50.0);
        c.work(&fg, &h, 21);
        c.dry();
    }
    if o.stage(&mut c, "underpaint") {
        return;
    }

    // ---------------------------------------------------------------- sky
    {
        let sky_mask = Mask::from_fn(f, |_, y| if y < 470.0 { 1.0 } else { 0.0 });
        let h = st.broad().color(sky).coverage(3.0).medium(0.3);
        c.work(&sky_mask, &h, 31);
        if let Some(b) = st.blend() {
            for p in 0..st.blend_passes {
                c.work(&sky_mask, &b, 32 + p as u64);
            }
        }
        c.dry();
        // stippled second layer: tiny touches, strokeless gradation
        let stip = paint::Handling::new(Tool::round_sable(3.0))
            .length(1.5, 4.0)
            .coverage(0.9)
            .mixed(&pal, 0.55)
            .mix_jitter(0.05)
            .color(|x, y| sky(x, y))
            .pressure(0.35, 0.6)
            .dips(6, 0.35, 0.5)
            .angle(|_, _| -1.3)
            .angle_jitter(0.6)
            .ramps(0.2, 0.4);
        c.work(&sky_mask, &stip, 35);
        c.dry();
    }
    if o.stage(&mut c, "sky") {
        return;
    }

    // ------------------------------------------------------------- clouds
    // long horizontal bars, lit from below by the sun still under the ridge
    {
        let bars: [(f32, f32, f32, f32); 6] = [
            (60.0, 470.0, 78.0, 9.0),
            (380.0, 820.0, 62.0, 7.0),
            (560.0, 1010.0, 128.0, 11.0),
            (-10.0, 330.0, 168.0, 8.0),
            (250.0, 610.0, 214.0, 6.0),
            (640.0, 940.0, 252.0, 5.0),
        ];
        for (i, &(x0, x1, y, th)) in bars.iter().enumerate() {
            let n = (th / 2.2).ceil() as usize + 1;
            let mut b = Held::new(Tool { ragged: 0.4, ..Tool::filbert(6.0) }, 100 + i as u64);
            let wob = Fbm::new(200 + i as u32, 3, 90.0);
            for k in 0..n {
                let s = k as f32 / (n - 1).max(1) as f32; // 0 top .. 1 bottom
                let yy = y - th * 0.5 + s * th;
                let lit = sky(0.5 * (x0 + x1), yy);
                let under = mix(hex("#a497a6"), hex("#e7bfae"), smoothstep(0.35, 1.0, s), Mix::Light);
                let col = mix(lit, under, 0.55 + 0.3 * (1.0 - (y / 260.0)), Mix::Light);
                b.reload(pal.paint(col, 0.5), 0.3);
                let inset = th * 2.0 * (1.0 - (2.0 * s - 1.0).abs()).max(0.0);
                let pts: Vec<(f32, f32)> = (0..=12)
                    .map(|j| {
                        let t = j as f32 / 12.0;
                        let x = x0 + (x1 - x0) * t - inset * (0.5 - t);
                        (x, yy + wob.get(x, y) * 5.0 + (t - 0.5).powi(2) * 8.0)
                    })
                    .collect();
                c.drag(&mut b, &Gesture::new(pts).pressure(0.6, 0.45).ramps(0.3, 0.35).orient(Orient::Across), None);
            }
            // fuse the bar with a clean badger, lightly
            let mut bl = Held::new(Tool { pickup: 0.15, ..Tool::badger(18.0) }, 150 + i as u64);
            for k in 0..2 {
                let yy = y - th * 0.3 + k as f32 * th * 0.6;
                let pts: Vec<(f32, f32)> = (0..=8).map(|j| (x0 + (x1 - x0) * j as f32 / 8.0, yy + wob.get(x0 + (x1 - x0) * j as f32 / 8.0, y) * 5.0)).collect();
                c.drag(&mut bl, &Gesture::new(pts).pressure(0.35, 0.3), None);
                bl.wipe(0.9);
            }
        }
        c.dry();
    }
    if o.stage(&mut c, "clouds") {
        return;
    }

    // ----------------------------------------------- the ridges, far to near
    for (k, r) in ridges.iter().enumerate() {
        let sc = f.scale;
        let m = Mask::from_fn(f, |x, y| {
            let d = y - r.crest(x);
            ((d * sc + 0.5).clamp(0.0, 1.0)) * (1.0 - smoothstep(r.depth * 0.7, r.depth, d))
        });
        let hd = paint::Handling::new(Tool { lay: 0.8, ..Tool::filbert(7.0 + k as f32) })
            .mixed(&pal, 0.4 - 0.03 * k as f32)
            .mix_jitter(0.05)
            .color(|x, y| r.color(x, y))
            .angle(|x, _| r.slope(x).atan() * 0.7)
            .angle_jitter(0.05)
            .length(30.0, 80.0)
            .coverage(3.0)
            .pressure(0.55, 0.8)
            .dips(2, 0.5, 0.6)
            .clip(true)
            .threshold(0.05);
        c.work(&m, &hd, 40 + k as u64);
        if let Some(b) = st.blend() {
            let b = b.clip(true).threshold(0.05).pressure(0.3, 0.4).length(60.0, 160.0);
            c.work(&m, &b, 60 + k as u64);
        }
        c.dry();
    }
    if o.stage(&mut c, "distance") {
        return;
    }

    // ---------------------------------------------------------- foreground
    // the ledge: dark earth and turf against the misted valley
    {
        let h = st.body()
            .color(|x, y| {
                let t = smoothstep(495.0, 620.0, y);
                let top = mix(hex("#4d4538"), hex("#5e5040"), (-((x - 300.0) / 200.0).powi(2)).exp(), Mix::Pigment);
                mix(top, hex("#2c2621"), t, Mix::Pigment)
            })
            .angle(|_, _| 0.05)
            .clip(true)
            .threshold(0.05);
        c.work(&ledge, &h, 70);
        c.dry();
    }
    // the tor, block by block from the bottom up
    for (i, (b, m)) in blocks.iter().zip(&bmasks).enumerate() {
        let (cx, cy, rx, ry) = (b.cx, b.cy, b.rx, b.ry);
        let col = move |x: f32, y: f32| -> Rgb {
            let (u, v) = ((x - cx) / rx, (y - cy) / ry);
            let face = mix(hex("#453d36"), hex("#2b2622"), smoothstep(-0.2, 1.0, v), Mix::Pigment);
            // the right side turns away from the light
            let face = mix(face, hex("#26221f"), smoothstep(0.2, 1.0, u) * 0.6, Mix::Pigment);
            // the left end turns toward the dawn
            let face = mix(face, hex("#5b4a3d"), smoothstep(-0.55, -1.0, u) * 0.7, Mix::Pigment);
            // the top plane catches the sky
            let top = mix(hex("#6e6a70"), hex("#5a5559"), smoothstep(-0.2, 0.6, u), Mix::Pigment);
            mix(face, top, smoothstep(-0.45, -0.75, v), Mix::Pigment)
        };
        let h = st.body()
            .color(col)
            .angle(move |x, y| {
                let (u, v) = ((x - cx) / rx, (y - cy) / ry);
                0.25 * u * v
            })
            .length(15.0, 45.0)
            .clip(true)
            .threshold(0.05);
        c.work(m, &h, 80 + i as u64);
        if let Some(bl) = st.blend() {
            let bl = bl.clip(true).threshold(0.05).pressure(0.3, 0.4).length(30.0, 80.0);
            c.work(m, &Handling_with(bl), 90 + i as u64);
        }
        c.dry();
        // the joint under the block and a few cracks
        let dark = pal.paint(hex("#1c1917"), 0.2);
        let mut br = Held::new(Tool::round_sable(2.2), 300 + i as u64);
        br.load(dark, 0.7);
        let low: Vec<(f32, f32)> = b.pts.iter().copied().filter(|p| p.1 > cy + ry * 0.55).collect();
        if low.len() > 2 {
            let mut low = low;
            low.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
            c.drag(&mut br, &Gesture::new(low).pressure(0.8, 0.7), None);
        }
        let mut rng = paint::Rng::new(400 + i as u64);
        for _ in 0..(rx / 40.0) as usize + 1 {
            br.reload(dark, 0.5);
            let x = cx + rng.range(-0.7, 0.7) * rx;
            let y0 = cy - ry * rng.range(0.3, 0.7);
            let pts = vec![(x, y0), (x + rng.normal() * 2.0, y0 + ry * 0.5), (x + rng.normal() * 3.0, cy + ry * 0.9)];
            c.drag(&mut br, &Gesture::new(pts).pressure(0.6, 0.3), Some(m));
        }
        // rim of dawn light on the upper left edges
        let rim = pal.paint(hex("#c4a483"), 0.45);
        let mut rb = Held::new(Tool::round_sable(1.6), 500 + i as u64);
        let n = b.pts.len();
        let mut run: Vec<(f32, f32)> = vec![];
        for j in 0..=n {
            let p = b.pts[j % n];
            let q = b.pts[(j + 1) % n];
            let (dx, dy) = (q.0 - p.0, q.1 - p.1);
            // outward normal for a clockwise-in-screen contour
            let (nx, ny) = (dy, -dx);
            let l = (nx * nx + ny * ny).sqrt().max(1e-4);
            let facing = (-nx / l) * 0.55 + (-ny / l) * 0.8;
            if facing > 0.35 {
                run.push((p.0 - nx / l * 1.2, p.1 - ny / l * 1.2));
            } else if run.len() > 1 {
                rb.reload(rim, 0.25);
                c.drag(&mut rb, &Gesture::new(std::mem::take(&mut run)).pressure(0.45, 0.25).ramps(0.2, 0.4), Some(m));
            } else {
                run.clear();
            }
        }
        c.dry();
    }
    if o.stage(&mut c, "tor") {
        return;
    }

    // ------------------------------------------------ spruces and the cross
    let tree_dark = pal.mix(hex("#1f2420")).color;
    let tree_rim = pal.mix(hex("#7a6a52")).color;
    for (i, &(x, y, hh)) in [(882.0, 300.0, 175.0), (935.0, 345.0, 135.0), (705.0, 322.0, 70.0), (962.0, 360.0, 90.0), (668.0, 350.0, 44.0)].iter().enumerate() {
        spruce(&mut c, &pal, (x, y), hh, tree_dark, tree_rim, 700 + i as u64);
    }
    c.dry();
    cross(&mut c, &pal, cross_at, 150.0, 800);
    c.dry();
    if o.stage(&mut c, "trees") {
        return;
    }

    // ----------------------------------------------------------- the figure
    {
        let cape = pal.mix(hex("#2d2f2a")).color;
        let dark = pal.mix(hex("#161412")).color;
        let hair = pal.mix(hex("#3a2c20")).color;
        let rim = pal.mix(hex("#9a8466")).color;
        paintings::figures::man_in_cape(&mut c, figure_at, 46.0, cape, dark, hair, Some(rim), 900);
        c.dry();
    }
    if o.stage(&mut c, "figure") {
        return;
    }

    // ------------------------------------------ grasses, last, upturned
    {
        let mut rng = paint::Rng::new(1000);
        let mut b = Held::new(Tool::round_sable(1.1), 1001);
        for k in 0..420 {
            let x = rng.range(-10.0, 640.0);
            let top = ledge_y(&ledge_pts, x);
            let y = top + rng.range(0.0, 1.0f32).powf(2.0) * 60.0 + 1.0;
            let lit = rng.chance(0.3);
            let col = if lit { hex("#7c6d4d") } else { hex("#2f2c22") };
            if k % 4 == 0 {
                b.reload(pal.paint(col, 0.25), 0.5);
            }
            let len = rng.range(5.0, 14.0) * (1.0 - (y - top) / 90.0);
            let lean = rng.normal() * 0.3 + 0.1;
            let pts = vec![(x, y), (x + lean * len * 0.5, y - len * 0.6), (x + lean * len, y - len)];
            c.drag(&mut b, &Gesture::new(pts).pressure(0.7, 0.1).ramps(0.0, 0.6), None);
        }
        c.dry();
    }
    if o.stage(&mut c, "grass") {
        return;
    }

    o.finish(&mut c, &Finish::aged(st.relief));
}

/// Identity helper (keeps the blend handling type explicit).
#[allow(non_snake_case)]
fn Handling_with(h: paint::Handling<'_>) -> paint::Handling<'_> {
    h
}

fn ledge_y(pts: &[(f32, f32)], x: f32) -> f32 {
    for w in pts.windows(2) {
        if x >= w[0].0 && x <= w[1].0 {
            let t = (x - w[0].0) / (w[1].0 - w[0].0);
            return w[0].1 + (w[1].1 - w[0].1) * t;
        }
    }
    pts[pts.len() - 1].1
}

/// A spruce as Friedrich places it: a straight dark spire of drooping
/// tiers, the trunk first, then tiers from the top down; the side toward the
/// dawn gets a few lean touches of light on the branch tips.
fn spruce(c: &mut Canvas, pal: &Palette, base: (f32, f32), height: f32, dark: Rgb, rim: Rgb, seed: u64) {
    let mut h = paint::Hand::new(base, height, seed);
    h.tremor = 0.002;
    let p = paint::Paint { color: dark, hiding: 0.92, stiff: 0.6 };
    let mut t = h.take(Tool::round_sable, 0.014, p, 0.6);
    h.mark(c, &mut t, paint::Mark { pts: &[(0.0, 0.0), (0.002, 0.5), (0.0, 1.0)], pressure: (0.9, 0.3), ramps: (0.0, 0.3) }, None);
    let mut b = h.take(Tool::round_sable, 0.026, p, 0.6);
    let tiers = 26 + (height / 10.0).min(20.0) as usize;
    let slim = h.rng.range(0.15, 0.2);
    let mut tips = vec![];
    for i in 0..tiers {
        let v = 0.97 - (i as f32 + h.rng.range(0.0, 0.6)) / tiers as f32 * 0.9;
        let reach = (0.012 + slim * (1.0 - v)) * h.rng.range(0.7, 1.1);
        if i % 3 == 0 {
            b.reload(p, 0.6);
        }
        for s in [-1.0f32, 1.0] {
            let droop = reach * h.rng.range(0.3, 0.5);
            let pts = [(s * 0.004, v), (s * reach * 0.55, v - droop), (s * reach, v - droop * 0.75)];
            h.mark(c, &mut b, paint::Mark { pts: &pts, pressure: (0.9, 0.35), ramps: (0.0, 0.5) }, None);
            if s < 0.0 {
                tips.push((s * reach * 0.8, v - droop * 0.7));
            }
        }
    }
    h.mark(c, &mut t, paint::Mark { pts: &[(0.0, 0.93), (0.001, 1.03)], pressure: (0.7, 0.2), ramps: (0.0, 0.5) }, None);
    c.dry();
    let lp = pal.paint(rim, 0.5);
    let mut l = h.take(Tool::round_sable, 0.01, lp, 0.3);
    for (k, &(u, v)) in tips.iter().enumerate() {
        if k % 2 == 0 {
            l.reload(lp, 0.3);
        }
        h.mark(c, &mut l, paint::Mark { pts: &[(u + 0.03, v + 0.004), (u, v)], pressure: (0.5, 0.3), ramps: (0.1, 0.5) }, None);
    }
}

/// A plain wooden cross: the upright set into a cleft, the crossbar pegged
/// on, a thin line of dawn light down the edge that faces the sun.
fn cross(c: &mut Canvas, pal: &Palette, at: (f32, f32), height: f32, seed: u64) {
    let wood = pal.paint(hex("#211c18"), 0.15);
    let mut b = Held::new(Tool { ragged: 0.2, ..Tool::round_sable(4.2) }, seed);
    for k in 0..2 {
        b.reload(wood, 0.9);
        let dx = k as f32 * 0.8 - 0.4;
        c.drag(&mut b, &Gesture::line((at.0 + dx, at.1 + 2.0), (at.0 + dx + 0.6, at.1 - height)).pressure(0.9, 0.85).ramps(0.02, 0.02).shake(0.3), None);
    }
    let bar_y = at.1 - height * 0.78;
    let half = height * 0.22;
    for k in 0..2 {
        b.reload(wood, 0.9);
        let dy = k as f32 * 0.8 - 0.4;
        c.drag(&mut b, &Gesture::line((at.0 - half, bar_y + dy + 0.8), (at.0 + half, bar_y + dy)).pressure(0.85, 0.85).ramps(0.03, 0.03).shake(0.3).orient(Orient::Across), None);
    }
    c.dry();
    let light = pal.paint(hex("#c9a47d"), 0.4);
    let mut r = Held::new(Tool::round_sable(1.0), seed + 1);
    r.load(light, 0.35);
    c.drag(&mut r, &Gesture::line((at.0 - 1.7, bar_y + 3.0), (at.0 - 1.5, at.1 - 20.0)).pressure(0.5, 0.2).ramps(0.1, 0.5).shake(0.3), None);
    r.reload(light, 0.35);
    c.drag(&mut r, &Gesture::line((at.0 - 1.8, at.1 - height + 2.0), (at.0 - 1.7, bar_y - 3.0)).pressure(0.45, 0.3).ramps(0.1, 0.3).shake(0.3), None);
    r.reload(light, 0.3);
    c.drag(&mut r, &Gesture::line((at.0 - half + 1.0, bar_y - 1.8), (at.0 - 3.0, bar_y - 1.9)).pressure(0.4, 0.2).ramps(0.1, 0.5).shake(0.3), None);
}

