/// A granite block of a tor: a rounded, slightly irregular box.
struct Block {
    cx: f32,
    cy: f32,
    rx: f32,
    ry: f32,
    pts: Vec<(f32, f32)>,
}

impl Block {
    fn new(cx: f32, cy: f32, rx: f32, ry: f32, seed: u32) -> Self {
        let n = Fbm::new(seed, 3, 1.3);
        let pts = (0..36)
            .map(|i| {
                let a = i as f32 / 36.0 * std::f32::consts::TAU;
                let (ca, sa) = (a.cos(), a.sin());
                // superellipse, flatter on top (weathered woolsack blocks)
                let p = if sa < 0.0 { 3.2 } else { 2.6 };
                let r = 1.0 / (ca.abs().powf(p) + sa.abs().powf(p)).powf(1.0 / p);
                let k = 1.0 + 0.07 * n.get(ca * 2.0, sa * 2.0);
                (cx + rx * r * ca * k, cy + ry * r * sa * k)
            })
            .collect();
        Block { cx, cy, rx, ry, pts }
    }
    fn mask(&self, c: &Canvas) -> Mask {
        Mask::from_shape(c.frame(), Shape::new().smooth_poly(&self.pts))
    }
    /// Normalized position inside the block.
    fn uv(&self, x: f32, y: f32) -> (f32, f32) {
        ((x - self.cx) / self.rx, (y - self.cy) / self.ry)
    }
}

