cd [local path redacted] && cat > [local path redacted] <<'EOF'
    // the tor, block by block from the bottom up: each block is a rounded
    // box lit by the dawn sky (tops), the glow at the left (left ends) and
    // in shadow toward us; the blocks part by value, not by outline
    {
        let mot = Fbm::new(320, 4, 30.0);
        let grain = Fbm::new(321, 3, 9.0);
        let mut rng = Rng::new(330);
        let dark = pal.paint(hex("#1a1715"), 0.2);
        let rim = pal.paint(hex("#b99a7c"), 0.45);
        let cool = pal.paint(hex("#7e7b84"), 0.45);
        for (i, b) in blocks.iter().enumerate() {
            // what of this block shows: its shape less the blocks in front
            let mut vis = Mask::from_shape(f, Shape::new().smooth_poly(&b.pts));
            for o2 in &blocks[i + 1..] {
                vis = vis.subtract(&Mask::from_shape(f, Shape::new().smooth_poly(&o2.pts)));
            }
            let seen_from_above = b.cy - b.ry * 0.6 > EYE;
            let col = |x: f32, y: f32| -> Rgb {
                let (u, v) = b.uv(x, y);
                let m = mot.get01(x, y) * 0.7 + grain.get01(x, y) * 0.3;
                let face = mix(hex("#2e2925"), hex("#40382f"), m, Mix::Pigment);
                // rounding toward the edges: normal turns left / right / up / down
                let left = smoothstep(-0.35, -0.95, u);
                let right = smoothstep(0.35, 0.95, u);
                let top = smoothstep(-0.4, -0.9, v);
                let bottom = smoothstep(0.4, 0.95, v);
                let mut s = mix(face, hex("#5c4838"), left * 0.75, Mix::Pigment);
                s = mix(s, hex("#1f1b19"), right * 0.55, Mix::Pigment);
                s = mix(s, hex("#191615"), bottom * 0.6, Mix::Pigment);
                if seen_from_above {
                    let lit = mix(hex("#6c6970"), hex("#80705f"), left, Mix::Pigment);
                    s = mix(s, lit, top * 0.9, Mix::Pigment);
                } else {
                    s = mix(s, hex("#4b4442"), top * 0.45, Mix::Pigment);
                }
                s
            };
            let (tilt, cx, cy, rx, ry) = (b.tilt, b.cx, b.cy, b.rx, b.ry);
            let h = st.body()
                .color(col)
                .angle(move |x, y| {
                    let (u, v) = ((x - cx) / rx, (y - cy) / ry);
                    // strokes follow the rounding: along the top and bottom,
                    // down the ends
                    let side = smoothstep(0.55, 0.95, u.abs()) * (1.0 - smoothstep(0.6, 0.95, v.abs()));
                    tilt + 0.25 * u * v + side * 1.3 * u.signum()
                })
                .length(8.0, 26.0)
                .coverage(3.5)
                .medium(0.12)
                .clip(true)
                .threshold(0.05);
            c.work(&vis, &h, 80 + i as u64);
            if let Some(bl) = st.blend() {
                let bl = bl.clip(true).threshold(0.05).pressure(0.25, 0.35).length(15.0, 40.0).angle(move |_, _| tilt);
                c.work(&vis, &bl, 180 + i as u64);
            }
            c.dry();
            // the shadowed seam where the block rests: only its flat underside
            let n = b.pts.len();
            let covered = |p: (f32, f32)| blocks[i + 1..].iter().any(|o2| o2.inside(p.0, p.1));
            let resting = |p: (f32, f32)| blocks[..i].iter().any(|o2| o2.inside(p.0, p.1 + 3.0));
            let mut jb = Held::new(Tool { ragged: 0.5, ..Tool::round_sable(1.8) }, 340 + i as u64);
            let mut run: Vec<(f32, f32)> = vec![];
            let mut seam = |c: &mut Canvas, run: &mut Vec<(f32, f32)>, jb: &mut Held| {
                if run.len() > 3 {
                    jb.reload(dark, 0.45);
                    c.drag(jb, &Gesture::new(std::mem::take(run)).pressure(0.7, 0.4).ramps(0.3, 0.4), None);
                }
                run.clear();
            };
            for j in 0..n {
                let p = b.pts[j];
                let (_, v) = b.uv(p.0, p.1);
                if v > 0.8 && resting(p) && !covered(p) {
                    run.push((p.0, p.1 - 0.5));
                } else {
                    seam(&mut c, &mut run, &mut jb);
                }
            }
            seam(&mut c, &mut run, &mut jb);
            // light caught along the upper edge: warm toward the dawn, cool on top
            let mut rb = Held::new(Tool::round_sable(1.3), 360 + i as u64);
            let mut last_warm = false;
            for j in 0..=n {
                let p = b.pts[j % n];
                let (u, v) = b.uv(p.0, p.1);
                let facing = v < -0.75 || (u < -0.85 && v < 0.3);
                if facing && !covered(p) {
                    run.push((p.0 + 0.8, p.1 + 1.2));
                    last_warm = u < -0.6;
                } else if run.len() > 3 {
                    rb.reload(if last_warm { rim } else { cool }, 0.2);
                    c.drag(&mut rb, &Gesture::new(std::mem::take(&mut run)).pressure(0.4, 0.2).ramps(0.25, 0.45), Some(&vis));
                } else {
                    run.clear();
                }
            }
            if run.len() > 3 {
                rb.reload(cool, 0.2);
                c.drag(&mut rb, &Gesture::new(std::mem::take(&mut run)).pressure(0.4, 0.2).ramps(0.25, 0.45), Some(&vis));
            }
            run.clear();
            // a weathering fissure or two, short and tapering
            let mut fb = Held::new(Tool::round_sable(1.1), 380 + i as u64);
            for _ in 0..(b.rx / 50.0) as usize + 1 {
                let x = b.cx + rng.range(-0.6, 0.6) * b.rx;
                let y0 = b.cy - b.ry * rng.range(0.5, 0.9);
                if front(x, y0) != Some(i) || rng.chance(0.3) {
                    continue;
                }
                fb.reload(dark, 0.35);
                let len = b.ry * rng.range(0.5, 1.2);
                let pts = vec![(x, y0), (x + rng.normal() * 1.2, y0 + len * 0.5), (x + rng.normal() * 2.0, y0 + len)];
                c.drag(&mut fb, &Gesture::new(pts).pressure(0.5, 0.1).ramps(0.1, 0.6), Some(&vis));
            }
            c.dry();
        }
        // lichen: sparse flat flecks of pale gray-green and ochre on the upper parts
        let mut lb = Held::new(Tool { ragged: 0.5, ..Tool::round_sable(2.0) }, 390);
        let mut k = 0;
        while k < 140 {
            let x = rng.range(520.0, 1000.0);
            let y = rng.range(270.0, 540.0);
            let Some(i) = front(x, y) else { continue };
            let (_, v) = blocks[i].uv(x, y);
            if v > -0.2 {
                continue;
            }
            if k % 3 == 0 {
                let col = if rng.chance(0.5) { hex("#5f6153") } else { hex("#6b5c43") };
                lb.reload(pal.paint(col, 0.45), 0.2);
            }
            k += 1;
            let l = rng.range(1.5, 3.5);
            c.drag(&mut lb, &Gesture::line((x, y), (x + l, y + rng.normal() * 0.4)).pressure(0.45, 0.3).ramps(0.2, 0.4), Some(&tor));
        }
        c.dry();
        // dwarf mountain pine (Knieholz) crouching on the ledges of the tor
        // and at its foot: set on the top edge of a block
        for (k, &(bi, u, r)) in [(0usize, -0.6f32, 20.0f32), (1, 0.5, 16.0), (4, -0.3, 12.0), (2, 0.55, 22.0), (6, -0.2, 11.0), (3, -0.1, 18.0)].iter().enumerate() {
            let b = &blocks[bi];
            let x = b.cx + u * b.rx;
            // walk down from above to the block's top edge
            let mut y = b.cy - b.ry * 1.3;
            while !b.inside(x, y) && y < b.cy {
                y += 0.5;
            }
            knieholz(&mut c, &pal, (x, y + 2.0), r, 400 + k as u64);
        }
        // and a couple on the ledge at the tor's foot
        knieholz(&mut c, &pal, (520.0, 498.0), 22.0, 420);
        knieholz(&mut c, &pal, (470.0, 505.0), 12.0, 421);
        c.dry();
    }
